using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Reflection;using System.Drawing;using System.Windows.Forms;using System.Web.Script.Serialization;

static class UpdateTests {
 static IEnumerable<Control> Controls(Control root){foreach(Control c in root.Controls){yield return c;foreach(var n in Controls(c))yield return n;}}
 static void Need(bool ok){if(!ok)throw new Exception("Assertion failed");}
 static void Reject(Action action){bool rejected=false;try{action();}catch(IOException){rejected=true;}catch(InvalidDataException){rejected=true;}Need(rejected);}
 public static int Run(string project,string output){Directory.CreateDirectory(output);StudioUsbGate.UseTestLock(Path.Combine(output,"fixture-device.lock"));Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var cases=new List<object>();var timings=new Dictionary<string,double>();int failed=0;Action<string,Action> test=(name,run)=>{try{run();cases.Add(new{name=name,status="PASS"});}catch(Exception e){failed++;cases.Add(new{name=name,status="FAIL",error=e.ToString()});}};string source=Path.Combine(project,"models","Developed by Conr4d.nam");var capture=NamCapture.Read(source,-5);byte[] original=NamCapture.AudioPayload(capture.Wave),raw=NamCapture.AudioPayload(NamCapture.Read(source).Wave);
  test("carrier_decode_roundtrip_is_byte_exact",()=>Need(NamCapture.AudioPayload(NamCapture.Encode(NamCapture.DecodePayload(original))).SequenceEqual(original)));
  test("zero_delta_preserves_audio_payload",()=>Need(NamCapture.AdjustPayload(original,0,0).SequenceEqual(original)));
  test("reference_automatic_returns_minus5",()=>{var watch=Stopwatch.StartNew();Need(NamLoudness.OutputFor(raw)==-5);timings["first_automatic_ms"]=watch.Elapsed.TotalMilliseconds;});
  test("automatic_compensates_output_gain_and_preserves_shape",()=>{byte[] louder=NamCapture.AdjustPayload(raw,0,6);var watch=Stopwatch.StartNew();double gain=NamLoudness.OutputFor(louder);timings["new_model_automatic_ms"]=watch.Elapsed.TotalMilliseconds;Need(Math.Abs(gain+11)<.051);byte[] normalized=NamCapture.AdjustPayload(louder,0,gain);Need(Math.Abs(NamLoudness.Measure(normalized)-NamLoudness.Target())<.051);});
  test("automatic_cached_result_is_stable",()=>{var watch=Stopwatch.StartNew();Need(NamLoudness.OutputFor(raw)==-5);timings["cached_automatic_ms"]=watch.Elapsed.TotalMilliseconds;});
  test("common_probe_linear_model_has_expected_level",()=>{var w=new double[1871];w[0]=1;w[1]=-1;w[3+5]=1;w[3+4*6+5]=1;w[1821+15]=1/1.01;w[1821+16+15]=-1/1.01;w[1870]=1;Need(Math.Abs(NamLoudness.Measure(NamCapture.AudioPayload(NamCapture.Encode(w)))+18)<.05);});
  test("silence_cannot_receive_fake_automatic_gain",()=>{var w=new double[1871];w[1870]=1;Reject(()=>NamLoudness.OutputFor(NamCapture.AudioPayload(NamCapture.Encode(w))));});
  test("delete_wire_body_names_only_chosen_slot",()=>Need(BitConverter.ToString(PodMsg.Encode(PodMsg.Map(102,1001,100,15,101,PodMsg.Map(112,51)))).Replace("-","").ToLowerInvariant()=="8366cd03e9640f65817033"));
  Func<NamFixtureDevice,string,NamDataSession> app=(device,name)=>new NamDataSession(Path.Combine(output,name),s=>{},(p,log)=>new PodWireSession(new NamWireFixture(device){OneTransferOnly=true},log));
  Func<byte[],string,NamFixtureDevice> loaded=(blob,title)=>new NamFixtureDevice{Stored=(byte[])blob.Clone(),Name=NamTitle.DeviceName(NamCapture.Sha(blob),title)};
  test("delete_saves_exact_backup_and_frees_slot",()=>{var device=loaded(original,"MY NAM");var session=app(device,"delete");try{session.Connect().GetAwaiter().GetResult();session.Delete(51,session.State.Bank[51]).GetAwaiter().GetResult();Need(device.DeleteRequests==1&&device.Stored==null&&!session.State.Bank[51].Used);Need(File.ReadAllBytes(Directory.GetFiles(Path.Combine(output,"delete"),"previous.float32.bin",SearchOption.AllDirectories).Single()).SequenceEqual(original));}finally{session.Disconnect().GetAwaiter().GetResult();}});
  test("delete_never_accepts_cabinet_ir",()=>{var device=new NamFixtureDevice{Stored=original,Name="MY CABINET"};var session=app(device,"protected-cab");try{session.Connect().GetAwaiter().GetResult();Reject(()=>session.Delete(51,session.State.Bank[51]).GetAwaiter().GetResult());Need(device.DeleteRequests==0&&device.Stored.SequenceEqual(original));}finally{session.Disconnect().GetAwaiter().GetResult();}});
  test("delete_rejects_forged_nam_tag",()=>{var device=new NamFixtureDevice{Stored=original,Name="NAM_000000000000 MY NAM"};var session=app(device,"forged-delete");try{session.Connect().GetAwaiter().GetResult();Reject(()=>session.Delete(51,session.State.Bank[51]).GetAwaiter().GetResult());Need(device.DeleteRequests==0);}finally{session.Disconnect().GetAwaiter().GetResult();}});
  test("delete_rejects_stale_slot_snapshot",()=>{var device=loaded(original,"MY NAM");var session=app(device,"stale-delete");try{session.Connect().GetAwaiter().GetResult();var selected=session.State.Bank[51];device.Name="MY CABINET";Reject(()=>session.Delete(51,selected).GetAwaiter().GetResult());Need(device.DeleteRequests==0);}finally{session.Disconnect().GetAwaiter().GetResult();}});
  test("builtin_zero_cannot_be_deleted",()=>{var device=loaded(original,"MY NAM");var session=app(device,"builtin-delete");try{session.Connect().GetAwaiter().GetResult();Reject(()=>session.Delete(-1,null).GetAwaiter().GetResult());Need(device.DeleteRequests==0);}finally{session.Disconnect().GetAwaiter().GetResult();}});
  foreach(bool keep in new[]{false,true}){bool preserve=keep;test(preserve?"delete_checks_slot_is_really_empty":"delete_checks_device_status",()=>{var device=loaded(original,"MY NAM");device.RefuseDelete=!preserve;device.KeepDeletedSlot=preserve;var session=app(device,preserve?"delete-still-used":"delete-refused");try{session.Connect().GetAwaiter().GetResult();Reject(()=>session.Delete(51,session.State.Bank[51]).GetAwaiter().GetResult());Need(device.Stored.SequenceEqual(original));}finally{session.Disconnect().GetAwaiter().GetResult();}});}
  test("volume_edit_keeps_slot_name_backup_and_input",()=>{string name="edit-levels",before=NamCapture.Sha(File.ReadAllBytes(source));var device=new NamFixtureDevice();var session=app(device,name);try{session.Connect().GetAwaiter().GetResult();session.Send(capture,51,false,session.State.Bank[51],"MY NAM").GetAwaiter().GetResult();session.ChangeVolume(51,session.State.Bank[51],-8).GetAwaiter().GetResult();Need(device.Slot==51&&device.Name.EndsWith(" MY NAM"));var expected=NamCapture.DecodePayload(NamCapture.AudioPayload(NamCapture.Read(source,-8).Wave));var actual=NamCapture.DecodePayload(device.Stored);Need(expected.Zip(actual,(a,b)=>Math.Abs(a-b)).Max()<1e-6);var record=session.Catalog.Find(device.Name);Need(record.InputDb==0&&record.OutputDb==-8);Need(NamCapture.Sha(File.ReadAllBytes(source))==before);Need(File.ReadAllBytes(Directory.GetFiles(Path.Combine(output,name),"previous.float32.bin",SearchOption.AllDirectories).Single()).SequenceEqual(original));}finally{session.Disconnect().GetAwaiter().GetResult();}});
  test("levels_edit_works_without_original_source_file",()=>{string copy=Path.Combine(output,"temporary-source.nam");File.Copy(source,copy);var device=new NamFixtureDevice();var session=app(device,"edit-moved-source");try{session.Connect().GetAwaiter().GetResult();session.Send(NamCapture.Read(copy,-5),51,false,session.State.Bank[51],"MY NAM").GetAwaiter().GetResult();File.Move(copy,copy+".moved");session.ChangeVolume(51,session.State.Bank[51],-7).GetAwaiter().GetResult();Need(session.Catalog.Find(device.Name).InputDb==0&&device.Slot==51);}finally{session.Disconnect().GetAwaiter().GetResult();}});
  test("levels_without_record_require_explicit_source_import",()=>{var device=loaded(original,"MY NAM");var session=app(device,"unknown-levels");try{session.Connect().GetAwaiter().GetResult();Reject(()=>session.ChangeVolume(51,session.State.Bank[51],-5).GetAwaiter().GetResult());Need(device.Stored.SequenceEqual(original));}finally{session.Disconnect().GetAwaiter().GetResult();}});
  test("out_of_range_level_never_writes",()=>{var device=loaded(original,"MY NAM");var session=app(device,"bad-levels");try{session.Connect().GetAwaiter().GetResult();Reject(()=>session.ChangeVolume(51,session.State.Bank[51],double.NaN).GetAwaiter().GetResult());Need(device.Stored.SequenceEqual(original));}finally{session.Disconnect().GetAwaiter().GetResult();}});
  foreach(bool deleting in new[]{false,true}){bool remove=deleting;test(remove?"delete_rejects_failed_flash_commit":"volume_rejects_failed_flash_commit",()=>{var device=new NamFixtureDevice();var session=app(device,remove?"delete-commit":"volume-commit");try{session.Connect().GetAwaiter().GetResult();session.Send(capture,51,false,session.State.Bank[51],"MY NAM").GetAwaiter().GetResult();device.RefuseCommit=true;if(remove)Reject(()=>session.Delete(51,session.State.Bank[51]).GetAwaiter().GetResult());else Reject(()=>session.ChangeVolume(51,session.State.Bank[51],-8).GetAwaiter().GetResult());}finally{session.Disconnect().GetAwaiter().GetResult();}});}
  test("volume_edit_preserves_existing_saturation_and_all_other_weights",()=>{var previous=NamCapture.Read(source,-5,-6);var device=new NamFixtureDevice();var session=app(device,"preserve-drive");try{session.Connect().GetAwaiter().GetResult();session.Send(previous,51,false,session.State.Bank[51],"MY NAM").GetAwaiter().GetResult();var before=NamCapture.DecodePayload(device.Stored);session.ChangeVolume(51,session.State.Bank[51],-8).GetAwaiter().GetResult();var after=NamCapture.DecodePayload(device.Stored);Need(Enumerable.Range(0,1870).All(i=>before[i]==after[i]));Need(Math.Abs(after[1870]/before[1870]-Math.Pow(10,-3.0/20))<1e-6);Need(session.Catalog.Find(device.Name).InputDb==-6);}finally{session.Disconnect().GetAwaiter().GetResult();}});
  test("one_volume_control_with_auto_in_main_and_dialog",()=>{UiText.Select("es");using(var window=new StudioWindow(true)){var nam=(Control)typeof(StudioWindow).GetField("nam",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(window);Need(Controls(nam).OfType<NumericUpDown>().Count()==1);Need(Controls(nam).OfType<CheckBox>().Single(c=>c.Name=="AutomaticVolume").Checked);Need(Controls(nam).OfType<DataGridView>().Single().Columns.Cast<DataGridViewColumn>().Any(c=>c.HeaderText=="Volumen"));}using(var dialog=new NamVolumeDialog(52,"MY NAM",new NamCatalogRecord{InputDb=-6,OutputDb=-5},original)){Need(Controls(dialog).OfType<NumericUpDown>().Count()==1&&dialog.VolumeDb==-5);}});
  test("empty_capture_prompt_is_readable_in_both_languages",()=>{foreach(string lang in new[]{"es","en"}){UiText.Select(lang);using(var window=new StudioWindow(true)){window.SetPreviewSize(new Size(1348,730));window.Render(Path.Combine(output,"empty-"+lang+".png"),false);var nam=typeof(StudioWindow).GetField("nam",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(window);var label=(Label)nam.GetType().GetField("captureInfo",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(nam);Need(TextRenderer.MeasureText(label.Text,label.Font,new Size(label.Width,10000),TextFormatFlags.WordBreak).Height<=label.Height);}}});
  UiText.Select("es");File.WriteAllText(Path.Combine(output,"results.json"),new JavaScriptSerializer().Serialize(new{status=failed==0?"PASS_OFFLINE_ONLY":"FAIL",cases=cases,timings=timings,USB_opened=false,SDK_started=false,physical_delete_or_levels_tested=false}));return failed==0?0:1;
 }
}
